interface PriceService { price(sku: string): Promise<number> }

const fakePrices = {
  async price(sku: string): Promise<number> {
    if (sku !== 'A-1') throw new Error(`no canned price for ${sku}`);
    return 9.99;
  },
} satisfies PriceService;

const checkout = new Checkout(fakePrices);

const server = setupServer(
  http.get('/price/:sku', ({ params }) => {
    const price = params.sku === 'A-1' ? 9.99 : null;
    return price === null ? new HttpResponse(null, { status: 404 })
                          : HttpResponse.json({ price });
  })
);
beforeAll(() => server.listen());
